import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import starlightLinksValidator from 'starlight-links-validator';
import starlightSidebarTopics from 'starlight-sidebar-topics';
import rehypeConsoleSlug from './src/console-slug.mjs';

// Sub-headings come from research/page-titles.tsv through scripts/to_starlight.py, which writes the groups that
// have them page by page; a group without them is autogenerated.
const SUBGROUPS_FILE = new URL('./src/sidebar-subgroups.json', import.meta.url);
const SUBGROUPS = existsSync(SUBGROUPS_FILE) ? JSON.parse(readFileSync(SUBGROUPS_FILE, 'utf8')) : {};
const groupItems = (dir) =>
  SUBGROUPS[dir]
    ? SUBGROUPS[dir].map((s) => ({ label: s.en, translations: { ja: s.ja }, items: s.items }))
    : [{ autogenerate: { directory: dir } }];
const group = (en, ja, dir, collapsed = false) => ({
  label: en, translations: { ja }, collapsed, items: groupItems(dir),
});
// The topic labels, shared with scripts/to_starlight.py, which titles the cards of the landing page with them.
const LABELS = JSON.parse(readFileSync(new URL('./src/topic-labels.json', import.meta.url), 'utf8'));

// The sidebar is built from the directories this build actually has. Pages reach src/content/docs/ from two places:
// the agent-fleet release (guide/, which gains task pages under user/ as the rewrite lands) and the pilot drafts
// (docs/pilot/, left out when DOCS_PILOT=0). A group for a directory that is not there, or a page that is in no
// group, fails the build or leaves a dead link in the top bar (the link validator does not check this config).
const CONTENT = new URL('./src/content/docs/', import.meta.url);
// Either language counts: the task pages are written in Japanese first.
const has = (dir) => existsSync(new URL(dir, CONTENT)) || existsSync(new URL(`ja/${dir}`, CONTENT));
const groups = (...defs) => defs.filter(([, , dir]) => has(dir)).map((d) => group(...d));

const userTopic = {
  // The task pages are written in Japanese first, so the topic lands on a page that exists in both languages.
  id: 'user', label: LABELS.user, icon: 'open-book', link: '/user/',
  items: [
    // Every group of the page map (research/page-titles.tsv), in its order. A directory that is not there yet is
    // skipped, so a lane that adds the first page of a group needs no change here.
    ...groups(
      ['Getting started', 'はじめに', 'user/start'],
      ['Sessions', 'セッション', 'user/sessions'],
      ['Many sessions', 'たくさんのセッション', 'user/fleet'],
      ['Agents', 'エージェント', 'user/agents'],
      ['Code', 'コード', 'user/code'],
      ['Files and terminal', 'ファイルとターミナル', 'user/files'],
      ['Preview and browser', 'プレビューとブラウザ', 'user/preview'],
      ['Chat and memos', 'チャットとメモ', 'user/chat'],
      ['Working as a team', 'チームで使う', 'user/team'],
      ['Integrations', '連携', 'user/integrations'],
      ['Workspace', 'ワークスペース', 'user/workspace'],
      ['Images', '画像', 'user/images'],
      ['Memory', 'メモリ', 'user/memory'],
      ['Settings', '設定', 'user/settings'],
      ['Using it from outside', '外部から使う', 'user/outside'],
      ['Security', 'セキュリティ', 'user/security'],
      ['Troubleshooting', '困ったとき', 'user/troubleshooting'],
    ),
    // The old shelf, only while the pinned release still ships it.
    ...(has('member') ? [group('All chapters (current layout)', '全章（現行の構成）', 'member', true)] : []),
  ],
};

// The reference pages directly under ref/, in the reading order of research/page-titles.tsv; a page the TSV does
// not list yet follows by name, so a new page is never left out. ref/cli, ref/mcp and ref/releases have groups or a
// topic of their own and are not repeated here.
const TITLES_FILE = new URL('./research/page-titles.tsv', import.meta.url);
const refPages = () => {
  const dir = new URL('ref/', CONTENT);
  if (!existsSync(dir)) return [];
  const built = new Set(readdirSync(dir).filter((f) => f.endsWith('.md') && f !== 'index.md').map((f) => f.slice(0, -3)));
  const ordered = existsSync(TITLES_FILE)
    ? readFileSync(TITLES_FILE, 'utf8').split('\n').map((l) => l.split('\t')[0])
        .filter((id) => /^ref\/[^/]+$/.test(id)).map((id) => id.slice(4)).filter((name) => built.delete(name))
    : [];
  return [...ordered, ...[...built].sort()].map((name) => ({ slug: `ref/${name}` }));
};

const referenceItems = [
  ...(has('ref') ? [{ slug: 'ref' }] : []),
  ...refPages(),
  ...groups(['Commands', 'コマンド', 'ref/cli'], ['MCP tools', 'MCP ツール', 'ref/mcp']),
];

// One topic per reader, like the shelves of guide/; each topic has its own sidebar.
const topics = [
  userTopic,
  {
    label: LABELS.admin, icon: 'setting', link: '/admin/',
    items: [{ autogenerate: { directory: 'admin' } }],
  },
  {
    id: 'operate', label: LABELS.operate, icon: 'rocket', link: '/operate/',
    items: [
      { label: 'Guide', translations: { ja: 'ガイド' }, items: [{ autogenerate: { directory: 'operate' } }] },
      // The runbooks are hidden from autogenerate (scripts/to_starlight.py) and listed here, so the group gets a
      // real label. The list is deploy/release/stage-docs.sh's RUNBOOKS; a slug that is not built fails the build,
      // but a runbook added there is not listed until it is added here too.
      {
        label: 'Runbooks', translations: { ja: 'Runbook' },
        items: ['compose', 'native', 'wsl', 'aws-ec2-single', 'aws-ecs', 'kubernetes']
          .map((name) => ({ slug: `operate/runbooks/${name}` })),
      },
    ],
  },
  {
    label: LABELS.ref, icon: 'information', link: '/ref/',
    items: referenceItems,
  },
  {
    label: LABELS.releases, icon: 'list-format', link: '/ref/releases/summary/',
    items: [{ autogenerate: { directory: 'ref/releases' } }],
  },
];

export default defineConfig({
  site: 'https://agent-fleet.org',
  base: '/docs',
  trailingSlash: 'always',
  markdown: { rehypePlugins: [rehypeConsoleSlug] },
  integrations: [
    starlight({
      title: 'Agent Fleet',
      customCss: ['./src/styles/custom.css'],
      // The product site's header links and a site title that leads to the product top; on phones, a menu and the
      // language and theme selects on pages without a sidebar (the splash landing page), the links in the mobile menu
      // on the others.
      components: {
        Header: './src/components/Header.astro',
        MobileMenuFooter: './src/components/MobileMenuFooter.astro',
      },
      logo: { src: './src/assets/icon.png' },
      favicon: '/favicon.png',
      defaultLocale: 'root',
      locales: {
        root: { label: 'English', lang: 'en' },
        ja: { label: '日本語', lang: 'ja' },
      },
      social: [{ icon: 'github', label: 'GitHub', href: 'https://github.com/k-k1/agent-fleet' }],
      lastUpdated: false,
      // Search ranking, measured with scripts/search_quality.mjs (README.md, "Search quality"). Starlight's own
      // defaults (pageLength 0.1, termFrequency 0.1, termSaturation 2, termSimilarity 9) put long chapters that
      // use the two halves of a segmented Japanese term ahead of the short task page about it. These are Pagefind's
      // defaults, except termSaturation: they weigh page length and term frequency again, and an exact word no
      // longer outbids a closer one.
      pagefind: { ranking: { pageLength: 0.75, termFrequency: 1, termSaturation: 2, termSimilarity: 1 } },
      plugins: [
        starlightSidebarTopics(topics),
        starlightLinksValidator({ errorOnRelativeLinks: false }),
      ],
    }),
  ],
});
